() => {
  const r = {ready: document.documentElement.dataset.ready, scrollH: document.body.scrollHeight, inner: innerHeight};
  const pick = {h1:'h1', photo:'.photo', cands:'.cands', cta:'.cta', steps:'.steps', footer:'footer'};
  r.boxes = {};
  for (const k in pick){const b=document.querySelector(pick[k]).getBoundingClientRect(); r.boxes[k]=[Math.round(b.x),Math.round(b.y),Math.round(b.width),Math.round(b.height)];}
  const img=document.querySelector('.photo img'); r.imgNat=[img.naturalWidth,img.naturalHeight];
  r.overflow=[...document.querySelectorAll('h1,p,span,footer')].map(e=>({t:e.textContent.slice(0,18),ov:e.scrollWidth-e.clientWidth}));
  return r;
}

