async () => {
  const out={};
  for (const f of ['portrait.png','wide.png','sky.png']) {
    const im = new Image();
    await new Promise((res,rej)=>{im.onload=res;im.onerror=rej;im.src='/'+f+'?t='+Date.now();});
    out[f]=[im.naturalWidth,im.naturalHeight];
  }
  return out;
}

